function w2s(p,v){return{x:v.x+v.w/2+(p.x-v.cam.x)*v.cam.s,y:v.y+v.h/2-(p.y-v.cam.y)*v.cam.s};}function s2w(p,v){return{x:v.cam.x+(p.x-v.x-v.w/2)/v.cam.s,y:v.cam.y-(p.y-v.y-v.h/2)/v.cam.s};}
function path(points,v,close=false){ctx.beginPath();points.forEach((p,i)=>{const s=w2s(p,v);i?ctx.lineTo(s.x,s.y):ctx.moveTo(s.x,s.y);});if(close)ctx.closePath();}
