document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||$('#modal').open)return;if(e.code==='Space'){e.preventDefault();space=true;}if(e.key==='Escape'){draft=[];drag=null;setTool('select');}if(e.key==='Enter')finishShape();if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();downloadProject();}});document.addEventListener('keyup',e=>{if(e.code==='Space')space=false;});
