$('#new-project').onclick=()=>{modal('Start a new design','<p>Your current project remains available with Undo. Download a project file if you want a separate copy.</p><div class="modal-actions"><button id="new-confirm" class="primary">Create blank design</button></div>');$('#new-confirm').onclick=()=>{$('#modal').close();resetProject(fresh());};};$('#demo-btn').onclick=()=>{resetProject(demo());addDemoUpper();change();fit();};
$('#add-floor').onclick=()=>{modal('Add a floor',`<div class="formgrid"><label>Name<input id="new-floor-name" value="Level ${p.floors.length+1}"></label><label>Elevation (${unit()})<input id="new-floor-elevation" type="number" value="${nfmt(Math.max(...p.floors.map(f=>f.elevation))+3.6)}"></label></div><label class="inline"><input type="checkbox" id="copy-floor" checked> Copy current floor layout, including stair links</label><div class="modal-actions"><button class="primary" id="add-floor-confirm">Add floor</button></div>`);$('#add-floor-confirm').onclick=()=>{const elevation=Number($('#new-floor-elevation').value)*meter();if(!Number.isFinite(elevation))return;remember();const f=$('#copy-floor').checked?structuredClone(floor()):fresh().floors[0];const ids=new Map;for(const e of [...f.walls,...f.doors,...f.rooms,...(f.stairs||[]),...f.obstacles,...f.traces])ids.set(e.id,uid());for(const e of [...f.walls,...f.doors,...f.rooms,...(f.stairs||[]),...f.obstacles,...f.traces]){e.id=ids.get(e.id);if(e.wallId)e.wallId=ids.get(e.wallId);if(e.roomId)e.roomId=ids.get(e.roomId);}f.id=uid();f.name=$('#new-floor-name').value||'New floor';f.elevation=elevation;f.doors.forEach(d=>{if(d.exit)d.discharge='none';});p.floors.push(f);p.activeFloor=p.floors.length-1;mode='building';$('#modal').close();change();fit();};};
$('#settings-btn').onclick=()=>{modal('Project + floor settings',`<div class="callout">Rule set: IBC 2021 teaching subset (A / B / E / M), plus selected ADA walking-surface checks. Local amendments and special occupancies require review.</div><div class="formgrid">${propertyInput('Floor name','none',floor().name)}<label>Floor elevation (${unit()})<input id="floor-elevation" type="number" value="${nfmt(floor().elevation)}"></label><label>Default occupancy<select id="default-group">${['A','B','E','M'].map(v=>`<option ${p.settings.group===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Analysis grid (m)<select id="grid-size">${[.15,.3,.5].map(v=>`<option value="${v}" ${p.settings.grid===v?'selected':''}>${v} m</option>`).join('')}</select></label></div><label class="inline"><input type="checkbox" id="sprinkler" ${p.settings.sprinkler?'checked':''}> NFPA 13 sprinkler protection throughout</label><br><label class="inline"><input type="checkbox" id="voice" ${p.settings.voice?'checked':''}> Qualifying emergency voice / alarm system</label><div class="modal-actions"><button id="settings-save" class="primary">Apply settings</button></div>`);$('#settings-save').onclick=()=>{remember();floor().name=$('#modal-content input[data-prop]').value;floor().elevation=Number($('#floor-elevation').value)*meter();p.settings={...p.settings,group:$('#default-group').value,grid:Number($('#grid-size').value),sprinkler:$('#sprinkler').checked,voice:$('#voice').checked};$('#modal').close();change();};};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}function downloadProject(){download(new Blob([JSON.stringify(p)],{type:'application/json'}),p.name.replace(/[^a-z0-9_-]/gi,'_')+'.egress.json');toast('Project file downloaded. It includes all floors, site layers and reference geometry.');}$('#save-project').onclick=downloadProject;$('#open-project').onclick=()=>$('#project-input').click();$('#project-input').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>60e6)throw Error('Project exceeds the 60 MB limit.');resetProject(validateProject(JSON.parse(await f.text())));}catch(err){toast(err.message);}e.target.value='';};
$('#import-btn').onclick=()=>$('#drawing-input').click();
$('#drawing-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;const ext=file.name.split('.').pop().toLowerCase();if(file.size>35e6)return toast('Use a 2D drawing under 35 MB. Remove unused blocks, hatches and 3D objects.');if(['png','jpg','jpeg','pdf'].includes(ext)){try{let src,width,height;if(ext==='pdf'){toast('Rendering the first PDF page…');const pdfjs=await import('../vendor/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('../vendor/pdf.worker.min.mjs',import.meta.url).href;const doc=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise,page=await doc.getPage(1),vp=page.getViewport({scale:Math.min(2,2400/page.getViewport({scale:1}).width)}),c=document.createElement('canvas');c.width=vp.width;c.height=vp.height;await page.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;src=c.toDataURL('image/png');width=c.width;height=c.height;await doc.destroy();}else{src=await new Promise(resolve=>{const r=new FileReader;r.onload=()=>resolve(r.result);r.readAsDataURL(file);});const im=new Image;im.src=src;await im.decode();width=im.width;height=im.height;}modal('Place a reference drawing',`<p>${esc(file.name)} · ${width} × ${height} pixels</p><div class="formgrid"><label>Full image width (${unit()})<input id="image-width" type="number" value="${p.units==='ft'?100:30}" min="0.1"></label><label>Origin X (${unit()})<input id="image-x" type="number" value="0"></label><label>Origin Y (${unit()})<input id="image-y" type="number" value="0"></label></div><p class="callout">Enter the real width of the complete image. You can also use the two-point calibration tool after placement. PDF import renders page 1; export one floor per PDF.</p><div class="modal-actions"><button id="image-place" class="primary">Place reference</button></div>`);$('#image-place').onclick=()=>{const w=Number($('#image-width').value)*meter();if(!(w>0))return;remember();target().image={src,name:file.name,width:w,height:w*height/width,x:Number($('#image-x').value)*meter(),y:Number($('#image-y').value)*meter()};$('#modal').close();change();fit();toast('Reference placed. Use Import → calibrate if you need to set a known distance.');};}catch(err){toast('Import failed: '+err.message);}return;}
if(!['dwg','3dm','dxf'].includes(ext))return toast('Choose a DWG, Rhino 3DM, DXF, PDF or image.');modal('Reading '+ext.toUpperCase(),'<p>Decoding the drawing on your computer…</p><div class="callout">The CAD parser runs in a separate worker. Large DWG drawings may take a moment. Original files are not uploaded to a server.</div>');let cadWorker=new Worker(new URL('./cad-worker.mjs',import.meta.url),{type:'module'});const timer=setTimeout(()=>{cadWorker.terminate();$('#modal-content').innerHTML='<p>The drawing took too long to decode. Export a smaller 2D model-space drawing with only the needed layers.</p>';},60000);cadWorker.onmessage=e=>{clearTimeout(timer);cadWorker.terminate();if(!e.data.ok){$('#modal-content').innerHTML=`<p>${esc(e.data.error)}</p>`;return;}showCadImport(e.data.data,file.name);};cadWorker.onerror=e=>{clearTimeout(timer);cadWorker.terminate();$('#modal-content').innerHTML=`<p>CAD decoder error: ${esc(e.message)}. Check your connection and try again.</p>`;};const bytes=await file.arrayBuffer();cadWorker.postMessage({bytes,format:ext},[bytes]);};
function showCadImport(data,name){if(!data.segments.length){$('#modal-content').innerHTML='<p>No supported 2D curve geometry was found. Export model-space lines, polylines and curves; meshes and surfaces are not plan boundaries.</p>';return;}const ignored=Object.entries(data.ignored).map(([k,n])=>`${n} ${k}`).join(', '),unitOptions={'0.001':'Millimeters','0.01':'Centimeters','1':'Meters','0.0254':'Inches','0.3048':'Feet','0.9144':'Yards'};$('#modal-title').textContent='Import CAD geometry';$('#modal-content').innerHTML=`<p><b>${esc(name)}</b><br>${data.segments.length.toLocaleString()} segments · detected units: ${esc(data.unitName)}</p><div class="formgrid"><label>Drawing units<select id="cad-units">${Object.entries(unitOptions).map(([k,v])=>`<option value="${k}" ${Math.abs(Number(k)-(data.unitScale||1000)/1000)<1e-8?'selected':''}>${v}</option>`).join('')}</select></label><label>Place into<select id="cad-placement"><option value="reference">Reference geometry</option>${mode==='building'?'<option value="walls">Wall centerlines</option>':''}</select></label></div><div class="cad-layers">${data.layers.map(l=>`<label><input type="checkbox" data-cad-layer="${esc(l.id)}" ${l.visible?'checked':''}>${esc(l.name)}<small>${data.segments.filter(s=>s.layer===l.id).length}</small></label>`).join('')}</div><label class="inline"><input type="checkbox" id="cad-near" checked> Move selected drawing near the origin</label><br><label class="inline"><input type="checkbox" id="cad-project"> Project non-planar curves onto XY (explicit flattening)</label><p class="callout">Curves are tessellated into editable plan segments. Use a wall-centerline layer for conversion; keep double-line walls and door symbols as reference and trace their analysis geometry. ${ignored?'<br><b>Not imported:</b> '+esc(ignored):''}${data.warnings.length?'<br>'+esc(data.warnings.join(' ')):''}</p><div class="modal-actions"><button class="primary" id="cad-confirm">Import selected layers</button></div>`;$('#cad-confirm').onclick=()=>{const chosen=new Set($$('[data-cad-layer]:checked').map(el=>el.dataset.cadLayer)),scale=Number($('#cad-units').value),segs=data.segments.filter(s=>chosen.has(s.layer)&&s.visible!==false);if(!segs.length)return toast('Select at least one layer containing geometry.');if(segs.length>35000)return toast('Select fewer layers (maximum 35,000 reference segments).');let minX=Infinity,minY=Infinity,minZ=Infinity,maxZ=-Infinity;for(const s of segs)for(const q of [s.a,s.b]){minX=Math.min(minX,q[0]);minY=Math.min(minY,q[1]);minZ=Math.min(minZ,q[2]);maxZ=Math.max(maxZ,q[2]);}if((maxZ-minZ)*scale>.01&&!$('#cad-project').checked)return toast('Selected curves span multiple elevations. Select one 2D layer or explicitly enable XY projection.');const near=$('#cad-near').checked,group=uid();const converted=segs.map(s=>({a:{x:(s.a[0]-(near?minX:0))*scale,y:(s.a[1]-(near?minY:0))*scale},b:{x:(s.b[0]-(near?minX:0))*scale,y:(s.b[1]-(near?minY:0))*scale},layer:group+':'+s.layer,visible:s.visible}));if($('#cad-placement').value==='walls'&&converted.length>1500)return toast('Wall conversion is limited to 1,500 segments per import. Import dense drawings as reference.');remember();target().cad.push(...converted);target().layers.push(...data.layers.filter(l=>chosen.has(l.id)).map(l=>({...l,id:group+':'+l.id,name:name+' / '+l.name,visible:l.visible})));target().imports??=[];target().imports.push({name,format:data.format,units:data.unitName,scale,shift:{x:near?minX*scale:0,y:near?minY*scale:0},ignored:data.ignored,warnings:data.warnings});if($('#cad-placement').value==='walls')floor().walls.push(...converted.map(s=>({id:uid(),a:{...s.a},b:{...s.b},thickness:.15})));$('#modal').close();change();fit();toast('Drawing imported. Define the floor boundary, room areas and valid door openings before analyzing.');};}
function cadToWalls(id){const segs=target().cad.filter(s=>s.layer===id);if(segs.length>1500)return toast('This layer is too dense for wall conversion. Trace the circulation boundaries.');modal('Convert CAD layer to walls',`<p>Convert ${segs.length} line segments into walls with ${fmt(.15)} thickness?</p><p class="callout">Use centerlines. A double-line wall drawing creates two barriers, and both need openings. Door symbols do not become functional openings automatically.</p><button id="convert-walls" class="primary">Convert to editable walls</button>`);$('#convert-walls').onclick=()=>{remember();floor().walls.push(...segs.map(s=>({id:uid(),a:{...s.a},b:{...s.b},thickness:.15})));$('#modal').close();change();};}
function guide(){modal('Design, test, improve',`<p><a href="https://github.com/doubleteng/tengteng/tree/main/teaching/egress" target="_blank" rel="noopener">Application source</a> · <a href="./THIRD_PARTY.md" target="_blank" rel="noopener">Licenses + CAD decoder source</a></p><div class="help-step"><b>1</b><div><strong>Draw or import</strong><p>Start with a floor boundary, then add rooms, walls and doors. Import DWG, DXF or 2D Rhino linework; choose layers and confirm units. Images and PDFs are reference drawings.</p></div></div><div class="help-step"><b>2</b><div><strong>Connect the whole journey</strong><p>Add matching stair links on each floor. On the site, draw walkable areas, obstacles and real public-way connections. Mark assembly points separately.</p></div></div><div class="help-step"><b>3</b><div><strong>Play with the design</strong><p>Drag objects or their handles. Checks update after each edit. Use All floors to edit plans side by side, Play to follow paths, and a baseline to compare changes.</p></div></div><div class="help-step"><b>4</b><div><strong>Explain the result</strong><p>Click a check to find the issue. Trace common paths and dead ends, confirm the net/gross area basis, and export a report with the assumptions and unresolved checks.</p></div></div><div class="callout">Enter: finish shape · Escape: cancel · Delete: remove selection · Ctrl/Cmd+Z: undo · Ctrl/Cmd+S: save file · Space + drag: pan · scroll: zoom<br>Visibility controls affect display only. Hidden analysis walls and obstacles still count.</div>${target().image?'<button id="calibrate-start">Calibrate image using two points</button>':''}`);if($('#calibrate-start'))$('#calibrate-start').onclick=()=>{$('#modal').close();setTool('calibrate');$('#hint').textContent='Click the two ends of a known distance on the image.';};}
$('#help-btn').onclick=guide;
$('#scope-btn').onclick=()=>modal('Check scope + sources',`<p><b>IBC 2021 educational subset.</b> The app checks selected A, B, E and M cases. It does not certify Michigan Building Code compliance or apply local amendments automatically.</p><ul><li>Sampled exit-access travel and geometric connectivity</li><li>Occupant-load calculations using the selected function and area basis</li><li>Door clear widths, basic exit separation and load-based doorway counts</li><li>Linked protected-stair assumptions and ground-floor connections to the public way</li><li>Manually traced common paths and dead ends</li><li>Selected ADA walking-route width/slope checks and pedestrian–vehicle crossing review</li></ul><p>Fire ratings, hardware, intervening-space legality, mixed occupancy, fixed-seat assembly, full stair/ramp design, corridor minima, discharge capacity and accessible means of egress remain review items. Route playback does not predict evacuation time.</p><div class="source-list"><p><a href="${sources.ibc}" target="_blank" rel="noopener">ICC · 2021 IBC Means of Egress ↗</a><br><a href="${sources.ada}" target="_blank" rel="noopener">U.S. Access Board · ADA Chapter 4 ↗</a><br><a href="https://www.michigan.gov/lara/bureau-list/bcc/rules-acts/codes/code-books" target="_blank" rel="noopener">Michigan adopted codes ↗</a><br><a href="./THIRD_PARTY.md" target="_blank">CAD decoder licenses + source ↗</a></p></div>`);
$('#report-btn').onclick=()=>{if(!analysis||analyzedRevision!==revision)return toast('Wait for the current design checks before exporting.');const image=canvas.toDataURL('image/png'),complete=analysis.complete;const html=`<!doctype html><html><head><title>${esc(p.name)} — Egress + Site report</title><style>body{font:12px/1.6 Arial,sans-serif;color:#26352f;margin:35px}h1{font-size:26px}h2{margin-top:28px;border-bottom:1px solid #ccc}table{border-collapse:collapse;width:100%;font-size:11px}td,th{border:1px solid #ddd;padding:7px;text-align:left;vertical-align:top}th{background:#edf2ea}.fail{color:#a54035}.review{color:#937023}.pass{color:#2c6a49}img{width:100%;max-height:550px;object-fit:contain}button{padding:12px}@media print{button{display:none}h2,h3{break-after:avoid}tr{break-inside:avoid}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button><h1>${esc(p.name)}</h1><p>Egress + Site Lab · ${new Date().toLocaleString()}<br>IBC 2021 teaching subset · ${p.settings.sprinkler?'NFPA 13 throughout assumed':'No full sprinkler allowance'} · ${p.settings.voice?'Voice/alarm assumed':'No voice/alarm reduction'}<br>Results refer to the modeled geometry and assumptions; they are not a complete code determination.</p><img src="${image}" alt="Design overview"><h2>Complete building-to-site routes</h2><table><tr><th>Floor / room</th><th>Connection</th><th>Total route</th></tr>${complete.map(r=>`<tr><td>${esc(p.floors[r.floor].name)} / ${esc(r.name)}</td><td>${r.complete?'Connected to public way':'Connection requires review'}</td><td>${fmt(r.distance)} (includes user-entered stair travel)</td></tr>`).join('')}</table>${analysis.floors.map((r,i)=>`<h2>${esc(p.floors[i].name)}</h2><p>${r.total} occupants · ${r.exits} identified exits · analysis grid ${fmt(r.gridStep||0)}</p><table><tr><th>Status</th><th>Check</th><th>Evidence / next step</th><th>Reference</th></tr>${r.checks.map(c=>`<tr><td class="${c.status}">${c.status.toUpperCase()}</td><td>${esc(c.title)}</td><td>${esc(c.detail)}</td><td>${esc(c.ref)}</td></tr>`).join('')}</table>`).join('')}<h2>Source drawings</h2>${p.floors.map(f=>`<p>${esc(f.name)}: ${(f.imports||[]).map(i=>esc(i.name)+'; omitted: '+esc(JSON.stringify(i.ignored))).join('<br>')||'Drawn in app'}</p>`).join('')}<h2>References</h2><p><a href="${sources.ibc}">ICC 2021 IBC Means of Egress</a><br><a href="${sources.ada}">ADA Chapter 4</a></p></body></html>`;const win=window.open('','_blank');if(win){win.document.open();win.document.write(html);win.document.close();}else download(new Blob([html],{type:'text/html'}),'egress-report.html');};
let cloudEndpoint='',cloudSource=null,cloudOrigin=null,cloudNonce='',cloudFrame=null;const cloudPending=new Map;
fetch('./cloud-config.json').then(r=>r.json()).then(c=>cloudEndpoint=c.endpoint||localStorage.getItem('egress-cloud-endpoint')||'').catch(()=>{});
window.addEventListener('message',e=>{const m=e.data;if(!m||m.nonce!==cloudNonce||!/^https:\/\/([a-z0-9-]+\.)?googleusercontent\.com$/.test(e.origin)&&e.origin!=='https://script.google.com')return;if(m.type==='egress-cloud-ready'){cloudSource=e.source;cloudOrigin=e.origin;const status=$('#cloud-status');if(status)status.textContent='Connected to your Google Drive.';if($('#cloud-save'))$('#cloud-save').disabled=false;if($('#cloud-list'))$('#cloud-list').disabled=false;}if(m.type==='egress-cloud-result'&&e.source===cloudSource){const pending=cloudPending.get(m.requestId);if(pending){clearTimeout(pending.timer);cloudPending.delete(m.requestId);m.error?pending.reject(Error(m.error)):pending.resolve(m.result);}}});
function cloudCall(request){return new Promise((resolve,reject)=>{if(!cloudSource)return reject(Error('Connect and authorize Google Drive first.'));const requestId=uid(),timer=setTimeout(()=>{cloudPending.delete(requestId);reject(Error('Google Drive did not respond in time. Your local project is still saved.'));},45000);cloudPending.set(requestId,{resolve,reject,timer});cloudSource.postMessage({type:'egress-cloud-request',nonce:cloudNonce,requestId,request},cloudOrigin);});}
function connectCloud(){if(!/^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(cloudEndpoint))return toast('Enter a deployed Google Apps Script /exec URL.');cloudSource=null;cloudOrigin=null;cloudNonce=uid();if(cloudFrame)cloudFrame.remove();cloudFrame=document.createElement('iframe');cloudFrame.title='Google Drive project storage';cloudFrame.src=cloudEndpoint+'?nonce='+cloudNonce;cloudFrame.style.cssText='width:100%;height:130px;border:1px solid #e1e7db;border-radius:6px';$('#cloud-frame').append(cloudFrame);$('#cloud-status').textContent='Connecting… If authorization is needed, open Google authorization below, then reconnect.';}
$('#cloud-btn').onclick=()=>{modal('Google Drive projects',`<p>Save all floors and the site to your Google Drive. Apps Script maintains a project index in Google Sheets.</p>${!cloudEndpoint?'<div class="callout">The website is ready for the Apps Script backend. Google account authorization and deployment are still required. Local saving and project downloads work now.</div>':''}<label>Apps Script deployment URL<input id="cloud-endpoint" style="width:100%;margin:8px 0" value="${esc(cloudEndpoint)}" placeholder="https://script.google.com/macros/s/…/exec"></label><div style="display:flex;gap:8px"><button id="cloud-connect">Connect</button><a id="google-authorize" href="${esc(cloudEndpoint||'https://script.google.com/home')}" target="_blank" rel="noopener">Open Google authorization ↗</a></div><p id="cloud-status">${cloudSource?'Connected.':'Not connected.'}</p><div id="cloud-frame"></div><div class="modal-actions"><button id="cloud-list" ${cloudSource?'':'disabled'}>My projects</button><button class="primary" id="cloud-save" ${cloudSource?'':'disabled'}>Save current project</button></div><div id="cloud-projects"></div><p><a href="https://github.com/doubleteng/tengteng/tree/main/scripts/egress" target="_blank" rel="noopener">Backend source and deployment instructions ↗</a></p>`);$('#cloud-connect').onclick=()=>{cloudEndpoint=$('#cloud-endpoint').value.trim();localStorage.setItem('egress-cloud-endpoint',cloudEndpoint);$('#google-authorize').href=cloudEndpoint;connectCloud();};$('#cloud-save').onclick=async()=>{try{$('#cloud-status').textContent='Saving…';const checks=analysis?.floors.flatMap(a=>a.checks)||[],result=await cloudCall({action:'save',id:p.id,project:p,summary:{occupants:analysis?.floors.reduce((n,a)=>n+a.total,0)||0,flags:checks.filter(c=>c.status==='fail').length,reviews:checks.filter(c=>c.status==='review').length}});$('#cloud-status').textContent='Saved to your Google Drive at '+new Date(result.updated).toLocaleTimeString();}catch(e){toast(e.message);}};$('#cloud-list').onclick=async()=>{try{const r=await cloudCall({action:'list'});$('#cloud-projects').innerHTML=r.projects.map(o=>`<div class="filecard"><span>${esc(o.name)}</span><button data-cloud-load="${esc(o.id)}">Open</button></div>`).join('')||'<p>No cloud projects yet.</p>';$$('[data-cloud-load]').forEach(b=>b.onclick=async()=>{try{const r=await cloudCall({action:'load',id:b.dataset.cloudLoad});resetProject(validateProject(r.project));$('#modal').close();}catch(e){toast(e.message);}});}catch(e){toast(e.message);}};if(cloudEndpoint)connectCloud();};
requestAnimationFrame(draw);restore();

function journeyPanel(x,y,w,h){ctx.fillStyle='#f1f4ec';ctx.fillRect(x,y,w,h);ctx.fillStyle='#6a846c';ctx.font='10px sans-serif';ctx.textAlign='left';ctx.fillText('CONNECTED DESIGN',x+25,y+34);ctx.font='22px sans-serif';ctx.fillStyle='#2e5b45';const n=analysis?.complete.filter(r=>r.complete).length||0,total=analysis?.complete.length||0;ctx.fillText(n+' / '+total+' routes connected',x+25,y+72);ctx.font='11px sans-serif';ctx.fillStyle='#7d8a76';ctx.fillText('Rooms → stairs → ground floor → public way',x+25,y+99);let yy=y+135;const links=[...new Set((analysis?.connections||[]).map(c=>c.link))];for(const link of links.slice(0,4)){ctx.fillStyle='#d9e6d4';ctx.fillRect(x+25,yy-12,w-50,30);ctx.fillStyle='#55774f';ctx.fillText('↕  '+link+' · linked across floors',x+36,yy+6);yy+=39;}ctx.fillStyle='#7d8a76';ctx.fillText('Try moving an exit. Watch the whole route change.',x+25,Math.min(y+h-40,yy+28));ctx.fillText('Use a baseline to compare your next design move.',x+25,Math.min(y+h-22,yy+48));}
